def agregar_item(inv, nombre, cantidad, precio):
    """
    Agrega o suma cantidad a un producto existente y actualiza su precio.
    Devuelve el inventario.
    """
    if nombre in inv:
        inv[nombre]['cantidad'] += cantidad
        inv[nombre]['precio'] = precio
    else:
        inv[nombre] = {'cantidad': cantidad, 'precio': precio}
    return inv

def quitar_item(inv, nombre, cantidad):
    """
    Resta cantidad. Si queda en 0 o menos, elimina el producto del dict. 
    Si no existe, no hace nada. Devuelve el inventario.
    """
    if nombre in inv:
        inv[nombre]['cantidad'] -= cantidad

        if inv[nombre]['cantidad'] <= 0:
            del inv[nombre]

    return inv

