def parsear_linea(linea: str) -> dict or None:
    partes = linea.split('|')
    if len(partes) != 3:
        return None

    nivel, timestamp, mensaje = partes

    return {
        'nivel': nivel.upper(),
        'fecha': timestamp,
        'mensaje': mensaje
    }

def filtrar_nivel(registros, nivel):
    """
    Filtra una lista de registros (dicts) para devolver solo aquellos con el nivel especificado.

    Args:
        registros (list): Lista de diccionarios, donde cada dict tiene la clave 'nivel'.
        nivel (str): El nivel a filtrar (ej: 'ERROR', 'INFO').

    Returns:
        list: Una nueva lista que contiene solo los registros cuyo 'nivel' coincide con el parámetro.
    """
    return [registro for registro in registros if registro.get('nivel') == nivel]

def contar_por_nivel(registros):
    """
    Recibe una lista de dicts con claves 'nivel', 'fecha' y 'mensaje'. 
    Devuelve un dict {nivel: cantidad}.
    """
    conteo = {}
    for registro in registros:
        nivel = registro.get('nivel')
        if nivel:
            conteo[nivel] = conteo.get(nivel, 0) + 1
    return conteo

def mas_grave(registros):
    if not registros:
        return None

    gravedad_orden = {"ERROR": 4, "WARN": 3, "INFO": 2, "DEBUG": 1}

    registro_mas_grave = registros[0]
    max_gravedad = gravedad_orden.get(registros[0]['nivel'], 0)

    for registro in registros[1:]:
        nivel_actual = registro['nivel']
        gravedad_actual = gravedad_orden.get(nivel_actual, 0)

        if gravedad_actual > max_gravedad:
            max_gravedad = gravedad_actual
            registro_mas_grave = registro

    return registro_mas_grave

