def agregar(carrito, producto, cantidad, precio):
    for item in carrito:
        if item['producto'] == producto:
            item['cantidad'] += cantidad
            return carrito

    nuevo_item = {
        'producto': producto,
        'cantidad': cantidad,
        'precio': precio
    }
    carrito.append(nuevo_item)
    return carrito

def subtotal(carrito):
    """
    Calcula el subtotal del carrito sumando cantidad * precio de todas las líneas.

    Args:
        carrito: Una lista de diccionarios, donde cada diccionario tiene
                 'producto' (str), 'cantidad' (int) y 'precio' (float).

    Returns:
        float: La suma total de (cantidad * precio) de todos los productos.
    """
    total = 0.0
    for item in carrito:
        # Se asume que 'cantidad' es un entero y 'precio' es un flotante
        total += item['cantidad'] * item['precio']
    return total

def aplicar_descuento(monto, porcentaje):
    if 0 <= porcentaje <= 100:
        descuento_factor = 1 - (porcentaje / 100)
        return monto * descuento_factor
    else:
        return monto

def resumen(carrito, porcentaje):
    """
    Devuelve un dict con las claves 'lineas' (cantidad de productos distintos), 
    'subtotal' y 'total' (el subtotal con el descuento aplicado).
    """
    # Asumiendo que subtotal y aplicar_descuento están disponibles en el scope
    # para este ejercicio, aunque no se proporcionaron.

    # Cálculo de líneas (productos distintos)
    productos_distintos = set()
    for item in carrito:
        productos_distintos.add(item['producto'])

    lineas = len(productos_distintos)

    # Cálculo del subtotal (asumiendo que subtotal(carrito) existe)
    # Si no existe, se implementa aquí para que el código sea ejecutable
    def subtotal(carrito):
        return sum(item['cantidad'] * item['precio'] for item in carrito)

    subtotal_valor = subtotal(carrito)

    # Cálculo del total (asumiendo que aplicar_descuento(monto, porcentaje) existe)
    # Si no existe, se implementa aquí para que el código sea ejecutable
    def aplicar_descuento(monto, porcentaje):
        if 0 <= porcentaje <= 100:
            return monto * (1 - (porcentaje / 100))
        return monto

    total_valor = aplicar_descuento(subtotal_valor, porcentaje)

    return {
        'lineas': lineas,
        'subtotal': subtotal_valor,
        'total': total_valor
    }
